/// <summary>
/// Developer form to seed NVOrderTemplate records (report-to-order-type mappings).
/// Not added to navigation menus by default; intended to be opened via Menu Item.
/// Safe to run multiple times — existing records are skipped (no duplicates).
/// </summary>
/// <remarks>
/// Usage: Open form, review InfoText, click "Fill Templates" to seed data.
/// Add new order types to NVOrderTemplateSeedData.run() and re-run as needed.
/// </remarks>
[Form]
public class NVOrderTemplateSeedForm extends FormRun
{
}

/// <summary>
/// Initializes the form.
/// </summary>
public void init()
{
    super();
}

/// <summary>
/// Returns count of existing NVOrderTemplate records.
/// </summary>
private int getTemplatesCount()
{
    return int642int((select count(RecId) from NVOrderTemplate).RecId);
}

/// <summary>
/// Shows a Yes/No confirmation dialog.
/// </summary>
private boolean confirmRun(str _title, str _message, DialogButton _defaultButton = DialogButton::No)
{
    return Box::yesNo(_message, _defaultButton, _title) == DialogButton::Yes;
}

/// <summary>
/// Runs the seed data class with confirmation and error handling.
/// </summary>
private void runFillTemplates()
{
    int existingCount = this.getTemplatesCount();

    // Soft warning if data already exists — do not hard block
    if (existingCount > 0)
    {
        if (!this.confirmRun(
                "Data already exists",
                strFmt("Table NVOrderTemplate already contains %1 record(s).\n\nExisting records will be skipped (no duplicates).\n\nDo you want to run the job anyway?",
                    existingCount),
                DialogButton::No))
        {
            return;
        }
    }

    if (!this.confirmRun(
            "Confirm seed (Templates)",
            strFmt("This will seed Order Template mappings.\n\nCompany: %1\n\nContinue?", curext()),
            DialogButton::No))
    {
        return;
    }

    try
    {
        setPrefix("Seed Order Templates");

        NVOrderTemplateSeedData seedData = new NVOrderTemplateSeedData();
        seedData.run();

        Box::info(
            strFmt("Order Template seed finished. Current record count: %1.\n\nCheck Infolog for details.",
                this.getTemplatesCount()),
            "Done");
    }
    catch (Exception::Error)
    {
        error("Order Template seed failed. Check Infolog for details.");
    }
}
